window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dbe5e41f084e74ed"]={"versions": [{"id": "FIG-dbe5e41f084e74ed", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Synchronisation des Herunterfahrens zwischen Master-Core und Slave-Cores im AUTOSAR-Basissoftware-Modul ECU State Manager (EcuM) auf einer Multicore-Architektur. Das Diagramm gliedert sich räumlich über zwei Core-Partitionen („Master Core“ und „Slave Core n“) und zeigt die Interaktion der EcuM-BSW-Instanzen mit dem Multicore-Betriebssystem (McOs).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Instanzen bzw. Lifelines mit dem Stereotyp «module»:</p>\n<ul class=\"fig-list\">\n<li><code>Master :EcuM</code> (ECU State Manager Instanz auf dem Master-Core)</li>\n<li><code>Master :McOs</code> (OS-Instanz bzw. Betriebssystem-Schnittstelle auf dem Master-Core)</li>\n<li><code>Slave n :EcuM</code> (ECU State Manager Instanz auf dem n-ten Slave-Core)</li>\n<li><code>:McOs</code> (OS-Instanz bzw. Betriebssystem-Schnittstelle auf dem Slave-Core)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenaufrufe und Interaktionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM_MainFunction()</code>: Synchroner Aufruf von <code>Master :EcuM</code> an <code>Slave n :EcuM</code></li>\n<li><code>SetEvent(TaskId, Mask)</code>: OS-Aufruf von <code>Slave n :EcuM</code> an die lokale OS-Instanz <code>:McOs</code></li>\n<li><code>WaitEvent(Mask)</code>: OS-Aufruf von <code>Master :EcuM</code> an die OS-Instanz <code>Master :McOs</code></li>\n<li><code>ShutdownAllCores(StatusType)</code>: OS-Abschaltaufruf von <code>Master :EcuM</code> an <code>Master :McOs</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf vollzieht sich in folgenden Schritten:</p>\n<ol class=\"fig-list\">\n<li><code>Master :EcuM</code> setzt ein internes Shutdown-Flag („Set a shutdown flag which can be read by all EcuMs of all slave cores“).</li>\n<li><code>Master :EcuM</code> ruft synchron über Core-Grenzen hinweg <code>EcuM_MainFunction()</code> auf <code>Slave n :EcuM</code> auf, woraufhin die Ausführungsbestätigung an den Master zurückkehrt.</li>\n<li>Beide Kerne führen parallel ihre jeweilige BSW-Deinitialisierung durch: „BSW De-Initialization on Master Core“ auf dem Master-Core sowie „BSW De-Initialization on Slave Core“ auf dem Slave-Core.</li>\n<li>Nach Abschluss der Deinitialisierung signalisiert <code>Slave n :EcuM</code> die Fertigstellung über den Aufruf <code>SetEvent(TaskId, Mask)</code> an die lokale Instanz <code>:McOs</code>.</li>\n<li>Auf dem Master-Core befindet sich <code>Master :EcuM</code> in einem Schleifen-Fragment <code>loop until all cores done</code> und wartet synchron mittels <code>WaitEvent(Mask)</code> an <code>Master :McOs</code> auf das Eintreffen der entsprechenden Signale aller Slave-Cores.</li>\n<li>Sobald alle Cores fertig sind, verlässt <code>Master :EcuM</code> die Schleife, setzt das Shutdown-Flag zurück („Unset the shutdown flag“) und ruft schließlich an <code>Master :McOs</code> den Systembefehl <code>ShutdownAllCores(StatusType)</code> auf.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das normative Shutdown-Synchronisationsprotokoll für Multicore-Systeme im Fixed-EcuM. Entwickler müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\">\n<li>Das Shutdown-Flag über Shared Memory oder Inter-Core-Kommunikation für alle Slave-EcuM-Instanzen lesbar bereitgestellt wird.</li>\n<li>Das Betriebssystem die Event-Mechanismen (<code>SetEvent</code>, <code>WaitEvent</code>) multicore-fähig unterstützt bzw. die Signalisierung der Fertigstellung eines Cores an den wartenden Master-Task übergeben wird.</li>\n<li>Nur der Master-Core nach erfolgreicher Synchronisation und Rücksetzen des Flags den finalen OS-Shutdown über <code>ShutdownAllCores(StatusType)</code> einleitet.</li>\n</ul>"}, {"id": "FIG-366336030d16e45f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Synchronisation des Herunterfahrens zwischen Master-Core und Slave-Cores im AUTOSAR-Basissoftware-Modul ECU State Manager (EcuM) auf einer Multicore-Architektur. Das Diagramm gliedert sich räumlich über zwei Core-Partitionen („Master Core“ und „Slave Core n“) und zeigt die Interaktion der EcuM-BSW-Instanzen mit dem Multicore-Betriebssystem (McOs).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Instanzen bzw. Lifelines mit dem Stereotyp «module»:</p>\n<ul class=\"fig-list\">\n<li><code>Master :EcuM</code> (ECU State Manager Instanz auf dem Master-Core)</li>\n<li><code>Master :McOs</code> (OS-Instanz bzw. Betriebssystem-Schnittstelle auf dem Master-Core)</li>\n<li><code>Slave n :EcuM</code> (ECU State Manager Instanz auf dem n-ten Slave-Core)</li>\n<li><code>:McOs</code> (OS-Instanz bzw. Betriebssystem-Schnittstelle auf dem Slave-Core)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenaufrufe und Interaktionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM_MainFunction()</code>: Synchroner Aufruf von <code>Master :EcuM</code> an <code>Slave n :EcuM</code></li>\n<li><code>SetEvent(TaskId, Mask)</code>: OS-Aufruf von <code>Slave n :EcuM</code> an die lokale OS-Instanz <code>:McOs</code></li>\n<li><code>WaitEvent(Mask)</code>: OS-Aufruf von <code>Master :EcuM</code> an die OS-Instanz <code>Master :McOs</code></li>\n<li><code>ShutdownAllCores(StatusType)</code>: OS-Abschaltaufruf von <code>Master :EcuM</code> an <code>Master :McOs</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf vollzieht sich in folgenden Schritten:</p>\n<ol class=\"fig-list\">\n<li><code>Master :EcuM</code> setzt ein internes Shutdown-Flag („Set a shutdown flag which can be read by all EcuMs of all slave cores“).</li>\n<li><code>Master :EcuM</code> ruft synchron über Core-Grenzen hinweg <code>EcuM_MainFunction()</code> auf <code>Slave n :EcuM</code> auf, woraufhin die Ausführungsbestätigung an den Master zurückkehrt.</li>\n<li>Beide Kerne führen parallel ihre jeweilige BSW-Deinitialisierung durch: „BSW De-Initialization on Master Core“ auf dem Master-Core sowie „BSW De-Initialization on Slave Core“ auf dem Slave-Core.</li>\n<li>Nach Abschluss der Deinitialisierung signalisiert <code>Slave n :EcuM</code> die Fertigstellung über den Aufruf <code>SetEvent(TaskId, Mask)</code> an die lokale Instanz <code>:McOs</code>.</li>\n<li>Auf dem Master-Core befindet sich <code>Master :EcuM</code> in einem Schleifen-Fragment <code>loop until all cores done</code> und wartet synchron mittels <code>WaitEvent(Mask)</code> an <code>Master :McOs</code> auf das Eintreffen der entsprechenden Signale aller Slave-Cores.</li>\n<li>Sobald alle Cores fertig sind, verlässt <code>Master :EcuM</code> die Schleife, setzt das Shutdown-Flag zurück („Unset the shutdown flag“) und ruft schließlich an <code>Master :McOs</code> den Systembefehl <code>ShutdownAllCores(StatusType)</code> auf.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das normative Shutdown-Synchronisationsprotokoll für Multicore-Systeme im Fixed-EcuM. Entwickler müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\">\n<li>Das Shutdown-Flag über Shared Memory oder Inter-Core-Kommunikation für alle Slave-EcuM-Instanzen lesbar bereitgestellt wird.</li>\n<li>Das Betriebssystem die Event-Mechanismen (<code>SetEvent</code>, <code>WaitEvent</code>) multicore-fähig unterstützt bzw. die Signalisierung der Fertigstellung eines Cores an den wartenden Master-Task übergeben wird.</li>\n<li>Nur der Master-Core nach erfolgreicher Synchronisation und Rücksetzen des Flags den finalen OS-Shutdown über <code>ShutdownAllCores(StatusType)</code> einleitet.</li>\n</ul>"}], "trans": [{"from": "FIG-dbe5e41f084e74ed", "to": "FIG-366336030d16e45f", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
